package com.dns.resolver

import java.util.concurrent.ConcurrentHashMap
import java.security.MessageDigest
import java.time.Instant
import java.util.UUID

data class DnsRecord(val domain: String, val ip: String, val ttl: Int, val ownerId: String)
data class AuditEntry(val timestamp: Instant, val action: String, val userId: String, val resourceId: String)
data class Session(val userId: String, val role: String, val tenantId: String)

object AuditLog {
    private val entries = mutableListOf<AuditEntry>()

    fun log(action: String, userId: String, resourceId: String) {
        entries.add(AuditEntry(Instant.now(), action, userId, resourceId))
    }

    fun getEntries(): List<AuditEntry> = entries.toList()
}

object DnsStore {
    private val records = ConcurrentHashMap<String, DnsRecord>()
    private val tenantRecords = ConcurrentHashMap<String, MutableSet<String>>()

    fun addRecord(record: DnsRecord, tenantId: String): String {
        val id = generateRecordId(record.domain, tenantId)
        records[id] = record
        tenantRecords.getOrPut(tenantId) { mutableSetOf() }.add(id)
        return id
    }

    fun getRecord(id: String): DnsRecord? = records[id]

    fun getTenantRecordIds(tenantId: String): Set<String> = tenantRecords[tenantId] ?: emptySet()

    fun deleteRecord(id: String, tenantId: String): Boolean {
        val record = records.remove(id)
        if (record != null) {
            tenantRecords[tenantId]?.remove(id)
            return true
        }
        return false
    }

    private fun generateRecordId(domain: String, tenantId: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        val input = "$domain:${System.nanoTime()}"
        return digest.digest(input.toByteArray())
            .joinToString("") { "%02x".format(it) }
            .substring(0, 16)
    }
}

class DnsResolver(private val session: Session) {

    fun resolve(domain: String): String? {
        val tenantRecords = DnsStore.getTenantRecordIds(session.tenantId)
        for (id in tenantRecords) {
            val record = DnsStore.getRecord(id)
            if (record != null && record.domain == domain) {
                AuditLog.log("RESOLVE", session.userId, id)
                return record.ip
            }
        }
        return null
    }

    fun addRecord(domain: String, ip: String, ttl: Int): String {
        val record = DnsRecord(domain, ip, ttl, session.userId)
        val id = DnsStore.addRecord(record, session.tenantId)
        AuditLog.log("ADD", session.userId, id)
        return id
    }

    fun deleteRecord(recordId: String): Boolean {
        val record = DnsStore.getRecord(recordId)
        if (record == null) {
            AuditLog.log("DELETE_FAILED_NOT_FOUND", session.userId, recordId)
            return false
        }

        if (!hasDeletePermission(record, recordId)) {
            AuditLog.log("DELETE_DENIED", session.userId, recordId)
            return false
        }

        val result = DnsStore.deleteRecord(recordId, session.tenantId)
        if (result) {
            AuditLog.log("DELETE_SUCCESS", session.userId, recordId)
        }
        return result
    }

    fun getRecordDetails(recordId: String): DnsRecord? {
        val record = DnsStore.getRecord(recordId)
        if (record != null) {
            AuditLog.log("VIEW", session.userId, recordId)
        }
        return record
    }

    private fun hasDeletePermission(record: DnsRecord, recordId: String): Boolean {
        if (session.role == "admin") return true
        if (record.ownerId == session.userId) return true
        val tenantRecords = DnsStore.getTenantRecordIds(session.tenantId)
        return tenantRecords.contains(recordId)
    }
}

fun main() {
    val tenantA = Session("user1", "user", "tenant-alpha")
    val tenantB = Session("user2", "user", "tenant-beta")

    val resolverA = DnsResolver(tenantA)
    val resolverB = DnsResolver(tenantB)

    val idA = resolverA.addRecord("internal.alpha.com", "10.0.1.1", 300)
    val idB = resolverB.addRecord("internal.beta.com", "10.0.2.1", 300)

    // Cross-tenant access attempt
    val leaked = resolverB.getRecordDetails(idA)
    println("Cross-tenant view result: $leaked")
}
